import java.util.Arrays;
import java.util.Comparator;

public final class MergeSortTest {

    private static final TestCase[] TESTS = {
        test("sorts primitive arrays", MergeSortTest::sortsPrimitiveArrays),
        test("sorts primitive subranges", MergeSortTest::sortsPrimitiveSubranges),
        test("sorts comparable arrays", MergeSortTest::sortsComparableArrays),
        test("sorts with comparator", MergeSortTest::sortsWithComparator),
        test("preserves stability", MergeSortTest::preservesStability),
        test("handles empty and singleton arrays", MergeSortTest::handlesEmptyAndSingletonArrays),
        test("rejects invalid primitive ranges", MergeSortTest::rejectsInvalidPrimitiveRanges),
        test("rejects null inputs", MergeSortTest::rejectsNullInputs),
    };

    private MergeSortTest() {
        // Test suite.
    }

    public static void main(String[] args) {
        for (TestCase test : TESTS) {
            test.run();
        }

        System.out.println("All MergeSort tests passed.");
    }

    private static TestCase test(String name, ThrowingRunnable action) {
        return new TestCase(name, action);
    }

    private static void run(String name, ThrowingRunnable action) {
        try {
            action.run();
        } catch (Throwable error) {
            throw new AssertionError("Test failed: " + name, error);
        }
    }

    private static void sortsPrimitiveArrays() {
        int[] values = {38, 27, 43, 10, 9, 82, 0};

        MergeSort.sort(values);

        assertArrayEquals(new int[] {0, 9, 10, 27, 38, 43, 82}, values, "primitive sort");
    }

    private static void sortsPrimitiveSubranges() {
        int[] values = {99, 38, 27, 43, 10, 7};

        MergeSort.sort(values, 1, 5);

        assertArrayEquals(new int[] {99, 10, 27, 38, 43, 7}, values, "primitive subrange sort");
    }

    private static void sortsComparableArrays() {
        String[] values = {"delta", "alpha", "charlie", "bravo"};

        MergeSort.sort(values);

        assertArrayEquals(new String[] {"alpha", "bravo", "charlie", "delta"}, values, "comparable sort");
    }

    private static void sortsWithComparator() {
        String[] values = {"bbb", "a", "cccc", "dd"};

        MergeSort.sort(values, Comparator.comparingInt(String::length).thenComparing(Comparator.naturalOrder()));

        assertArrayEquals(new String[] {"a", "dd", "bbb", "cccc"}, values, "comparator sort");
    }

    private static void preservesStability() {
        Item[] values = {
            new Item(2, "a"),
            new Item(1, "b"),
            new Item(2, "c"),
            new Item(1, "d")
        };

        MergeSort.sort(values, Comparator.comparingInt(item -> item.key));

        assertArrayEquals(
            new Item[] {
                new Item(1, "b"),
                new Item(1, "d"),
                new Item(2, "a"),
                new Item(2, "c")
            },
            values,
            "stable ordering"
        );
    }

    private static void handlesEmptyAndSingletonArrays() {
        int[] empty = {};
        int[] single = {5};

        MergeSort.sort(empty);
        MergeSort.sort(single);

        assertArrayEquals(new int[] {}, empty, "empty array");
        assertArrayEquals(new int[] {5}, single, "single element array");
    }

    private static void rejectsInvalidPrimitiveRanges() {
        expectThrows(IndexOutOfBoundsException.class, () -> MergeSort.sort(new int[] {1, 2, 3}, -1, 2));
        expectThrows(IndexOutOfBoundsException.class, () -> MergeSort.sort(new int[] {1, 2, 3}, 0, 4));
        expectThrows(IndexOutOfBoundsException.class, () -> MergeSort.sort(new int[] {1, 2, 3}, 2, 1));
    }

    private static void rejectsNullInputs() {
        expectThrows(IllegalArgumentException.class, () -> MergeSort.sort((int[]) null));
        expectThrows(IllegalArgumentException.class, () -> MergeSort.sort((int[]) null, 0, 0));
        expectThrows(IllegalArgumentException.class, () -> MergeSort.sort((String[]) null));
        expectThrows(IllegalArgumentException.class, () -> MergeSort.sort((String[]) null, Comparator.naturalOrder()));
        expectThrows(IllegalArgumentException.class, () -> MergeSort.sort(new String[] {"a"}, null));
    }

    private static void assertArrayEquals(int[] expected, int[] actual, String context) {
        if (!Arrays.equals(expected, actual)) {
            throw new AssertionError(
                context + " expected " + Arrays.toString(expected) + " but was " + Arrays.toString(actual)
            );
        }
    }

    private static <T> void assertArrayEquals(T[] expected, T[] actual, String context) {
        if (!Arrays.equals(expected, actual)) {
            throw new AssertionError(
                context + " expected " + Arrays.toString(expected) + " but was " + Arrays.toString(actual)
            );
        }
    }

    private static void expectThrows(Class<? extends Throwable> expectedType, ThrowingRunnable action) {
        try {
            action.run();
        } catch (Throwable thrown) {
            if (expectedType.isInstance(thrown)) {
                return;
            }

            throw new AssertionError(
                "Expected " + expectedType.getSimpleName() + " but got " + thrown.getClass().getSimpleName(),
                thrown
            );
        }

        throw new AssertionError("Expected " + expectedType.getSimpleName() + " but nothing was thrown");
    }

    private static final class TestCase {
        private final String name;
        private final ThrowingRunnable action;

        private TestCase(String name, ThrowingRunnable action) {
            this.name = name;
            this.action = action;
        }

        private void run() {
            MergeSortTest.run(name, action);
        }
    }

    private interface ThrowingRunnable {
        void run() throws Throwable;
    }

    private static final class Item {
        private final int key;
        private final String label;

        private Item(int key, String label) {
            this.key = key;
            this.label = label;
        }

        @Override
        public boolean equals(Object other) {
            if (this == other) {
                return true;
            }
            if (!(other instanceof Item)) {
                return false;
            }
            Item item = (Item) other;
            return key == item.key && label.equals(item.label);
        }

        @Override
        public int hashCode() {
            return 31 * key + label.hashCode();
        }

        @Override
        public String toString() {
            return "Item{" + "key=" + key + ", label='" + label + "'" + '}';
        }
    }
}

import java.util.Comparator;

public final class MergeSort {

    private MergeSort() {
        // Utility class.
    }

    public static void sort(int[] values) {
        int[] safeValues = requireValues(values);
        sort(safeValues, 0, safeValues.length);
    }

    public static void sort(int[] values, int fromInclusive, int toExclusive) {
        int[] safeValues = requireValues(values);
        validateRange(safeValues.length, fromInclusive, toExclusive);
        if (toExclusive - fromInclusive < 2) {
            return;
        }

        new IntMergeSorter(safeValues, fromInclusive, toExclusive).sort(fromInclusive, toExclusive);
    }

    public static <T extends Comparable<? super T>> void sort(T[] values) {
        sort(values, Comparator.naturalOrder());
    }

    public static <T> void sort(T[] values, Comparator<? super T> comparator) {
        T[] safeValues = requireValues(values);
        Comparator<? super T> safeComparator = requireComparator(comparator);
        if (safeValues.length < 2) {
            return;
        }

        new ObjectMergeSorter<>(safeValues, safeComparator).sort(0, safeValues.length);
    }

    private static <T> T requireValues(T values) {
        if (values == null) {
            throw new IllegalArgumentException("values must not be null");
        }
        return values;
    }

    private static <T> Comparator<? super T> requireComparator(Comparator<? super T> comparator) {
        if (comparator == null) {
            throw new IllegalArgumentException("comparator must not be null");
        }
        return comparator;
    }

    private static void validateRange(int length, int fromInclusive, int toExclusive) {
        if (fromInclusive < 0 || toExclusive > length || fromInclusive > toExclusive) {
            throw new IndexOutOfBoundsException(
                "Invalid range: [" + fromInclusive + ", " + toExclusive + ") for length " + length
            );
        }
    }

    private static int midpoint(int left, int right) {
        return left + (right - left) / 2;
    }

    private abstract static class MergeSorter {
        final void sort(int left, int right) {
            if (right - left < 2) {
                return;
            }

            int mid = midpoint(left, right);
            sort(left, mid);
            sort(mid, right);
            merge(left, mid, right);
        }

        abstract void merge(int left, int mid, int right);
    }

    private static final class IntMergeSorter extends MergeSorter {
        private final int[] values;
        private final int[] buffer;
        private final int bufferOffset;

        private IntMergeSorter(int[] values, int fromInclusive, int toExclusive) {
            this.values = values;
            this.buffer = new int[toExclusive - fromInclusive];
            this.bufferOffset = fromInclusive;
        }

        @Override
        void merge(int left, int mid, int right) {
            int bufferLeft = left - bufferOffset;
            System.arraycopy(values, left, buffer, bufferLeft, right - left);

            int leftIndex = bufferLeft;
            int leftEnd = bufferLeft + (mid - left);
            int rightIndex = leftEnd;
            int destIndex = left;
            int bufferRight = bufferLeft + (right - left);

            while (leftIndex < leftEnd && rightIndex < bufferRight) {
                if (buffer[leftIndex] <= buffer[rightIndex]) {
                    values[destIndex++] = buffer[leftIndex++];
                } else {
                    values[destIndex++] = buffer[rightIndex++];
                }
            }

            while (leftIndex < leftEnd) {
                values[destIndex++] = buffer[leftIndex++];
            }
        }
    }

    private static final class ObjectMergeSorter<T> extends MergeSorter {
        private final T[] values;
        private final Object[] buffer;
        private final Comparator<? super T> comparator;

        private ObjectMergeSorter(T[] values, Comparator<? super T> comparator) {
            this.values = values;
            this.comparator = comparator;
            this.buffer = new Object[values.length];
        }

        @Override
        void merge(int left, int mid, int right) {
            System.arraycopy(values, left, buffer, left, right - left);

            int leftIndex = left;
            int rightIndex = mid;
            int destIndex = left;
            int leftEnd = mid;
            int bufferRight = right;

            while (leftIndex < leftEnd && rightIndex < bufferRight) {
                @SuppressWarnings("unchecked")
                T leftValue = (T) buffer[leftIndex];
                @SuppressWarnings("unchecked")
                T rightValue = (T) buffer[rightIndex];

                if (comparator.compare(leftValue, rightValue) <= 0) {
                    values[destIndex++] = leftValue;
                    leftIndex++;
                } else {
                    values[destIndex++] = rightValue;
                    rightIndex++;
                }
            }

            while (leftIndex < leftEnd) {
                @SuppressWarnings("unchecked")
                T value = (T) buffer[leftIndex++];
                values[destIndex++] = value;
            }
        }
    }
}

